const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const credentials=JSON.parse(fs.readFileSync('S:/dracula-design/data/.test-admin.json','utf8'));const browser=await chromium.launch();const p=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.status()>=500)errors.push(r.status()+' '+r.url())});await p.goto('http://127.0.0.1:4181/admin/login?ui=classic');await p.locator('input[type=email]').fill(credentials.email);await p.locator('input[type=password]').fill(credentials.password);await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(1000);for(const path of ['products','orders','customers','legal-pages','translations','inquiries','settings','users']){await p.goto('http://127.0.0.1:4181/admin/'+path+'?ui=classic');await p.waitForTimeout(700);console.log(path,await p.locator('h1').allTextContents());if(path==='products')await p.screenshot({path:'outputs/dracula-design-office/preview-admin.png',fullPage:true});}console.log('ERRORS',errors);await browser.close();})();
